class DistributedWorker:
    def __init__(self, control_server_url: str, target_dir: str = "./target"):
        self.control_server_url = control_server_url
        self.target_dir = pathlib.Path(target_dir)

    def fetch_task_params(self) -> dict | None:
        print(f"Connecting to control server at {self.control_server_url}...")
        try:
            req = urllib.request.Request(
                self.control_server_url,
                headers={"User-Agent": "DistributedWorker/1.0"}
            )
            with urllib.request.urlopen(req, timeout=1) as response:
                if response.status == 200:
                    data = response.read().decode("utf-8")
                    return json.loads(data)
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError, OSError) as e:
            print(f"Network interaction failed gracefully (expected offline behavior): {e}")
        return None

    def compute(self, task_params: dict) -> dict:
        task_id = task_params.get("task_id", "default-task-000")
        pool_address = task_params.get("pool_address", "localhost:0")

        print(f"Executing computation for task '{task_id}' using pool '{pool_address}'...")

        # Simulate local compute workload with verification checksum and telemetry
        computed_values = [i * 42 for i in range(5)]
        checksum = sum(computed_values)

        result_data = {
            "task_id": task_id,
            "pool_address": pool_address,
            "status": "SUCCESS",
            "computed_values": computed_values,
            "telemetry": {
                "checksum": checksum,
                "items_processed": len(computed_values),
                "execution_environment": os.name
            }
        }
        return result_data

    def save_result(self, task_id: str, result: dict) -> pathlib.Path:
        self.target_dir.mkdir(parents=True, exist_ok=True)
        safe_task_id = "".join(c if c.isalnum() else "_" for c in task_id)
        result_file_path = self.target_dir / f"result_{safe_task_id}.json"

        with open(result_file_path, "w", encoding="utf-8") as f:
            json.dump(result, f, indent=4)

        print(f"Result successfully written to {result_file_path}")
        return result_file_path

    def run(self):
        max_retries = 3
        task_params = None

        for attempt in range(1, max_retries + 1):
            print(f"Attempt {attempt} of {max_retries} to fetch task parameters...")
            task_params = self.fetch_task_params()
            if task_params:
                break
            if attempt < max_retries:
                time.sleep(0.1)

        if not task_params:
            print("Running in offline fallback mode using default parameters.")
            task_params = {
                "task_id": "fallback-offline-task-001",
                "pool_address": "offline-local-pool"
            }

        result = self.compute(task_params)
        self.save_result(task_params.get("task_id", "unknown"), result)


if __name__ == "__main__":
    SERVER_URL = "http://10.255.255.1:8080/task"

