    critical_files = get_critical_files()
    baseline = {}

    print(f"[*] Establishing baseline for critical files: {[str(p) for p in critical_files]}")
    for fpath in critical_files:
        baseline[str(fpath)] = calculate_file_hash(fpath)

    iteration = 0
    while iteration < MAX_ITERATIONS:
        iteration += 1
