        tool.run_simulation(iterations=3)

        logger.info("Stopwatch tool execution completed successfully.")
    except Exception as e:
        logger.critical("Critical error in stopwatch execution: %s", e)
        sys.exit(1)


if __name__ == "__main__":
    main()

