def parse_sqlite_artifact(db_path: pathlib.Path, storage_list: list) -> None:
    """Safely queries SQLite artifacts if they are valid databases."""
    try:
        with open(db_path, "rb") as f:
            header = f.read(16)
        if not header.startswith(b"SQLite format 3"):
            return

        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
        cursor = conn.cursor()

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
        tables = [row[0] for row in cursor.fetchall()]
        storage_list.append({"path": str(db_path), "tables": tables})
        conn.close()
    except Exception as e:
        log_event(f"Note: Could not parse database {db_path}: {e}")


