    metadata = {
        "extension_dir": str(ext_path),
        "bookmarks_found": [],
        "history_found": [],
        "other_databases": [],
    }

    if not ext_path.exists():
        return metadata

    for root, _, files in os.walk(ext_path):
        for file in files:
            file_path = pathlib.Path(root) / file
            file_lower = file.lower()
            if file.endswith((".sqlite", ".db", "History", "Bookmarks")) or "bookmark" in file_lower or "history" in file_lower:
                if "bookmark" in file_lower:
                    parse_sqlite_artifact(file_path, metadata["bookmarks_found"])
                elif "history" in file_lower:
                    parse_sqlite_artifact(file_path, metadata["history_found"])
                else:
                    parse_sqlite_artifact(file_path, metadata["other_databases"])

    return metadata


