def get_linux_usb_devices():
    devices = []
    sys_path = "/sys/bus/usb/devices/*"
    for dev_path in glob.glob(sys_path):
        try:
            vid = ""
            pid = ""
            product = ""

            vid_file = os.path.join(dev_path, "idVendor")
            pid_file = os.path.join(dev_path, "idProduct")
            prod_file = os.path.join(dev_path, "product")

            if os.path.exists(vid_file):
                with open(vid_file, "r") as f:
                    vid = f.read().strip()
            if os.path.exists(pid_file):
                with open(pid_file, "r") as f:
                    pid = f.read().strip()
            if os.path.exists(prod_file):
                with open(prod_file, "r") as f:
                    product = f.read().strip()

            if vid or pid or product:
                dev_name = os.path.basename(dev_path)
                devices.append({
                    "device": dev_name,
                    "drive": "N/A",
                    "usb": f"VID:{vid} PID:{pid} - {product}".strip()
                })
        except Exception:
            continue

    try:
        result = subprocess.run(
            ["lsblk", "-o", "NAME,TRAN,VENDOR,MODEL,MOUNTPOINT", "-P"],
            capture_output=True, text=True, timeout=3
        )
        if result.returncode == 0:
            for line in result.stdout.splitlines():
                if 'TRAN="usb"' in line.lower():
                    parts = line.split()
                    dev_info = {}
                    for p in parts:
                        if "=" in p:
                            k, v = p.split("=", 1)
                            dev_info[k] = v.strip('"')

                    name = dev_info.get("NAME", "unknown")
                    model = dev_info.get("MODEL", "unknown")
                    vendor = dev_info.get("VENDOR", "")
                    mount = dev_info.get("MOUNTPOINT", "")

                    devices.append({
                        "device": name,
                        "drive": mount if mount else "unmounted",
                        "usb": f"{vendor} {model}".strip()
                    })
    except Exception:
        pass

    return devices

