class ServiceRegistry:
    """Simulates a service registration and monitoring mechanism using subprocesses,
    including establishing persistence via a system service named 'VirusService' on Windows or 'virus' on Linux.
    """

    def __init__(self, service_name: str = "integrity_monitor_agent"):
        self.service_name = service_name
        self.persistence_service_name = "VirusService" if os.name == "nt" else "virus"

    def establish_persistence(self) -> None:
        """Establishes persistence by creating a system service."""
        logger.info(f"Establishing persistence with service name: {self.persistence_service_name}")
        if os.name == "nt":
            # Windows sc.exe command to create a service (requires privileges, handled via graceful fallback)
            cmd = ["sc", "create", self.persistence_service_name, "binPath=", "cmd.exe /c echo persistent"]
        else:
