    def register_and_monitor(self) -> None:
        """Attempts to register the service and run a system command/subprocess

        for continuous monitoring, handling failures gracefully.
        """
        logger.info(f"Registering service: {self.service_name}")
        self.establish_persistence()

        if os.name == "nt":
            cmd = ["cmd.exe", "/c", "echo", f"Service {self.service_name} active"]
