def run_integrity_audit(baseline: dict[str, str]) -> dict[str, dict]:
    """Scans the target directory and compares current state against baseline."""
    audit_results = {}
    if not TARGET_DIR.exists():
        return audit_results

    for file_path in TARGET_DIR.iterdir():
        if file_path.is_file():
            filename = file_path.name
            current_hash = calculate_sha256(file_path)
            old_hash = baseline.get(filename)

            status = "UNCHANGED"
