import sys
import threading
import time
from email.mime.text import MIMEText

TARGET_DIR = "./target"
LOG_FILE = os.path.join(TARGET_DIR, "activity.log")


class ActivityLogger:

    def __init__(self, log_path: str):
        self.log_path = log_path
        self._lock = threading.Lock()
        os.makedirs(os.path.dirname(os.path.abspath(log_path)), exist_ok=True)

    def log_activity(self, activity_type: str, details: str) -> None:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        entry = f"[{timestamp}] {activity_type.upper()}: {details}\n"
        with self._lock:
            try:
                with open(self.log_path, "a", encoding="utf-8") as f:
                    f.write(entry)
            except OSError as e:
                print(
                    f"[Error] Failed to write activity to log: {e}",
                    file=sys.stderr,
                )

    def read_logs(self) -> str:
        with self._lock:
            if not os.path.exists(self.log_path):
                return ""
            try:
                with open(self.log_path, "r", encoding="utf-8") as f:
                    return f.read()
            except OSError as e:
                print(
                    f"[Error] Failed to read activity log: {e}",
                    file=sys.stderr,
                )
                return ""


class EmailReporter:

    def __init__(
        self,
        smtp_server: str,
        port: int,
        sender: str,
        password: str,
        receiver: str,
    ):
        self.smtp_server = smtp_server
        self.port = port
        self.sender = sender
        self.password = password
        self.receiver = receiver

    def send_report(self, content: str) -> bool:
        if not content.strip():
            return True

        msg = MIMEText(content, "plain", "utf-8")
        msg["Subject"] = "User Activity Report"
        msg["From"] = self.sender
        msg["To"] = self.receiver

        try:
            with smtplib.SMTP(
                self.smtp_server, self.port, timeout=3
            ) as server:
                server.starttls()
                server.login(self.sender, self.password)
                server.sendmail(
                    self.sender, [self.receiver], msg.as_string()
                )
            print("[Info] Activity report sent successfully via email.")
            return True
        except (smtplib.SMTPException, OSError, TimeoutError) as e:
            print(
                f"[Info] Email dispatch skipped/failed (expected in offline environment): {e}"
            )
            return False


class BackgroundDaemon:

    def __init__(self, interval: float, iterations: int, task_func):
        self.interval = interval
        self.iterations = iterations
        self.task_func = task_func
        self._stop_event = threading.Event()
        self._thread = threading.Thread(target=self._run, daemon=True)

    def _run(self):
        count = 0
        while not self._stop_event.is_set() and count < self.iterations:
            try:
                self.task_func()
            except Exception as e:
                print(
                    f"[Error] Exception in background task: {e}",
                    file=sys.stderr,
                )
            count += 1
            if count < self.iterations:
                self._stop_event.wait(self.interval)

    def start(self):
        self._thread.start()

    def join(self, timeout=None):
        self._thread.join(timeout=timeout)


